head.script:
// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS25100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    const array_grid = [grd_List];
    setResizeGrid(array_grid, 300);

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS25100.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS25100.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
        btn_search.setDisabled(false);
        btn_search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS25100.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name chb_ALL_onclick
 * @description chb_ALL 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_ALL_onclick = function() {
    try {
        // 전체선택
        scwin.allUnCheck();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS25100.chb_ALL_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() <= 0) {
            await $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }
        $c.stf.doLogSave("ULDINS25100.xml", SCREN_PROCS_TP_CD_07); // 로그 남기고..

        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        const title = "주권다운로드";
        const xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
        $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
        // grd_List.GridToExcel(title, "", "8");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS25100.btn_Excel_onclick" });
    }
};

