/**
 * @method
 * @name dts_COM_ATTR_TP_OnLoadCompleted
 * @description dts_COM_ATTR_TP 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_COM_ATTR_TP_OnLoadCompleted = function(rowcount) {
    try {
        dts_COM_ATTR_TP.setBroadcast(false);
        for (let i = dts_COM_ATTR_TP.getRowCount(); i > 0; i--) {
            if (dts_COM_ATTR_TP.getCellData(i, "VALUE") === "1") {
                dts_COM_ATTR_TP.setCellData(i, "TEXT", "1 주식회사");
            } else if (dts_COM_ATTR_TP.getCellData(i, "VALUE") === "2") {
                dts_COM_ATTR_TP.setCellData(i, "TEXT", "2 증권투자회사");
            }
        }
        dts_COM_ATTR_TP.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS25100.dts_COM_ATTR_TP_OnLoadCompleted" });
    }
};

