/**
 * @method
 * @name ins_search
 * @description 주권조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

